body.script:
//
window.SYKA_BLOGGER_CONFIG = {
  appBase: 'https://cdn.jsdelivr.net/gh/taufx98/sykabelajar_3.0@gh-pages',
  supabaseUrl: 'https://jrfogwueytiddnanetth.supabase.co',
  cloudinaryCloudName: 'sykabelajar',
  cloudinaryUploadPreset: 'sykabelajar_preset'
};

(function(){
  var root=document.getElementById('page-root');
  function loadCss(url){
    return new Promise(function(resolve,reject){
      var link=document.createElement('link');
      link.rel='stylesheet';
      link.href=url;
      link.onload=resolve;
      link.onerror=reject;
      document.head.appendChild(link);
    });
  }
  function loadJs(url){
    return new Promise(function(resolve,reject){
      var script=document.createElement('script');
      script.type='module';
      script.src=url;
      script.onload=resolve;
      script.onerror=reject;
      document.body.appendChild(script);
    });
  }
  Promise.all([
    loadCss(window.SYKA_BLOGGER_CONFIG.appBase+'/styles.min.css?v=11'),
    loadJs(window.SYKA_BLOGGER_CONFIG.appBase+'/app.js?v=11')
  ]).catch(function(error){
    console.error('[SykaBelajar] runtime load failed',error);
    root.innerHTML='<div class="blogger-noscript"><strong>SykaBelajar sedang memuat ulang.</strong><br/>Bundle aplikasi belum berhasil dimuat. Deployment bundle belum tersedia atau gagal dimuat.</div>';
  });
})();
//
